// Base64 readers for the certificate/key material generated by
// scripts/gen-certs.sh, for the inline tls_* route surfaces
// (tls_custom_ca, tls_client_cert, tls_client_key).

import * as fs from "node:fs";
import * as path from "node:path";
import { UPSTREAM_CERTS_DIR } from "../setup/constants.js";

function b64(file: string): string {
  return fs.readFileSync(path.join(UPSTREAM_CERTS_DIR, file)).toString("base64");
}

/** Base64 PEM of the good upstream CA (tls_custom_ca happy path). */
export function upstreamCABase64(): string {
  return b64("upstream-ca.crt");
}

/** Base64 PEM of an unrelated CA that signed nothing served (tls_custom_ca negative). */
export function wrongCABase64(): string {
  return b64("wrong-ca.crt");
}

/** Base64 PEM of Pomerium's upstream client certificate (tls_client_cert). */
export function clientCertBase64(): string {
  return b64("pomerium-client.crt");
}

/** Base64 PEM of the client certificate's private key (tls_client_key). */
export function clientKeyBase64(): string {
  return b64("pomerium-client.key");
}

/** Base64 PEM of a key that does NOT match pomerium-client.crt (mismatch case). */
export function mismatchedKeyBase64(): string {
  return b64("mismatched.key");
}
